<?php
namespace App\Http\Controllers;
use App\Models\User;use Illuminate\Http\Request;use Illuminate\Support\Facades\Hash;
class UserController extends Controller{private function admin(){abort_unless(auth()->user()?->isAdmin(),403);}public function index(){$this->admin();$users=User::orderBy('name')->paginate(20);return view('users.index',compact('users'));}public function store(Request $request){$this->admin();$data=$request->validate(['name'=>'required|string|max:120','email'=>'required|email|max:190|unique:users,email','password'=>'required|string|min:8','role'=>'required|in:admin,manager,technician,operator,viewer']);$data['password']=Hash::make($data['password']);$data['active']=true;User::create($data);return back()->with('ok','Usuário criado.');}public function toggle(Request $request,User $user){$this->admin();abort_if($user->id===$request->user()->id,422,'Não desative seu próprio usuário.');$user->update(['active'=>!$user->active]);return back()->with('ok','Status atualizado.');}}
